def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive_opps:
        return max(0.0, min(budget, 18.0 if hp > 3 and no_water == 0 else 45.0))

    expected_slots = supply / float(WATER_REQ)
    scarcity = 1.0
    if expected_slots <= 1.25:
        scarcity = 1.35
    elif expected_slots <= 1.5:
        scarcity = 1.18
    elif expected_slots >= 1.85:
        scarcity = 0.82
    elif expected_slots >= 1.65:
        scarcity = 0.92

    opp_bids = []
    threat_bids = []
    rich_count = 0
    desperate_count = 0

    for oid, opp in alive_opps:
        obudget = float(opp.get('budget', 0.0))
        ohp = float(opp.get('hp', 0.0))
        onw = int(opp.get('no_water_days', 0))
        if obudget >= 90:
            rich_count += 1
        if ohp <= 3 or onw >= 1:
            desperate_count += 1

        prev = opp.get('previous_trace') or {}
        pbid = prev.get('bid')
        if pbid is not None:
            pbid = float(pbid)
            opp_bids.append(pbid)
            weight = 1.0
            if obudget >= 120:
                weight += 0.25
            if ohp <= 3 or onw >= 1:
                weight += 0.2
            threat_bids.append(pbid * weight)

    highest_prev = max(opp_bids) if opp_bids else 0.0
    weighted_threat = max(threat_bids) if threat_bids else highest_prev

    urgency = 0.0
    if no_water >= 2:
        urgency += 40.0
    elif no_water == 1:
        urgency += 18.0
    if hp <= 2:
        urgency += 35.0
    elif hp <= 4:
        urgency += 16.0

    base = 42.0 * scarcity + urgency

    if weighted_threat >= 120:
        target = max(base, highest_prev + 2.5)
    elif weighted_threat >= 95:
        target = max(base, highest_prev + 1.5)
    elif weighted_threat > 0:
        target = max(base, highest_prev * 0.92 + 3.0)
    else:
        target = base

    if rich_count >= 2 and expected_slots < 1.6:
        target += 8.0
    if desperate_count >= 2 and hp > 4 and no_water == 0:
        target -= 10.0

    if day >= 8:
        target += 6.0
    if day >= 9 and (hp <= 4 or no_water >= 1):
        target += 10.0

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if days_left > 0:
        reserve_floor = min(budget * 0.45, days_left * 18.0)

    if hp > 5 and no_water == 0 and expected_slots >= 1.8 and highest_prev >= 100:
        target = min(target, 28.0)

    affordable = budget
    if budget > reserve_floor:
        affordable = max(0.0, budget - reserve_floor * 0.25)

    bid = min(target, affordable)

    if no_water >= 2 or hp <= 2:
        bid = min(budget, max(bid, highest_prev + 2.0, 88.0))
    elif no_water == 1 or hp <= 4:
        bid = min(budget, max(bid, 62.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # If we somehow have no budget, bid 0.
    if my_status['budget'] <= 0:
        return 0.0

    # Determine alive opponents and extract yesterday bids.
    alive_opps = []
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            if prev and prev.get('bid') is not None:
                try:
                    yesterday_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    # Supply pressure: fewer units per water requirement implies higher competition.
    # Use a conservative mapping to avoid fragile indexing.
    if supply <= MIN_SUPPLY:
        pressure = 1.0
    elif supply >= MAX_SUPPLY:
        pressure = 0.2
    else:
        # linear interpolation between MIN_SUPPLY and MAX_SUPPLY
        pressure = 1.0 - ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)) * 0.8
        if pressure < 0.2:
            pressure = 0.2
        if pressure > 1.0:
            pressure = 1.0

    # Baseline bid targets.
    # Goal: secure enough water to avoid no-water days cascading.
    hp = float(my_status['hp'])
    no_water_days = int(my_status.get('no_water_days', 0))
    budget = float(my_status['budget'])

    # If we are in danger, bid aggressively.
    if hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * (0.85 + 0.15 * pressure)
    else:
        # When safe, bid just enough to compete with aggressive bidders.
        # Use yesterday's max bid as a signal of market clearing price.
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            # If others were bidding near/above our daily salary, they likely overpay.
            # Counter by bidding moderately below that level.
            if highest_prev_bid >= DAILY_SALARY * 0.85:
                target = DAILY_SALARY * (0.35 + 0.25 * pressure)
            else:
                target = min(highest_prev_bid + 5.0, DAILY_SALARY * (0.55 + 0.25 * pressure))
        else:
            target = DAILY_SALARY * (0.45 + 0.25 * pressure)

    # Never exceed budget.
    if target > budget:
        target = budget

    # Add small day-based jitter to avoid exact ties.
    jitter = ((int(day) % 7) - 3) * 0.5
    target = target + jitter

    if target < 0:
        target = 0.0
    return float(target)

